<?php require_once __DIR__ . '/../auth/guard.php'; requireRole('student'); ?>
<style>
.kidss-quiz{max-width:1180px;margin:0 auto;padding:8px 2px 30px;color:#24355f}.kidss-quiz h1{font-size:1.8rem;font-weight:850;margin:0}.kq-muted{color:#6b7280}.kq-toolbar{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:18px 0}.kq-toolbar label{font-weight:700;display:block;margin-bottom:6px}.kq-toolbar select{min-width:230px;border:1px solid #dce1ec;border-radius:10px;padding:10px}.kq-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:18px}.kq-card{background:#fff;border:1px solid #e8ebf3;border-radius:20px;padding:22px;box-shadow:0 7px 20px rgba(40,55,100,.04)}.kq-image-wrap{height:340px;background:#f8f9fc;border-radius:16px;display:grid;place-items:center;overflow:hidden;margin:14px 0}.kq-image-wrap img{width:100%;height:100%;object-fit:contain}.kq-question{font-size:1.15rem;font-weight:800}.kq-answers{display:grid;grid-template-columns:1fr 1fr;gap:12px}.kq-answer{display:flex;align-items:center;gap:10px;min-height:64px;text-align:left;padding:12px;border:2px solid #e5e7ef;border-radius:14px;background:#fff;color:#24355f;font-weight:800}.kq-answer:hover:not(:disabled){border-color:#8b6be8;background:#faf8ff}.kq-answer.correct{border-color:#34a853;background:#ecf9f0}.kq-answer.wrong{border-color:#ef6262;background:#fff0f0}.kq-letter{width:32px;height:32px;flex:0 0 32px;display:grid;place-items:center;border-radius:10px;background:#f0ebff;color:#7048e8}.kq-progress{height:9px;border-radius:10px;background:#eceaf5;overflow:hidden;margin:14px 0}.kq-progress span{display:block;height:100%;background:#7048e8}.kq-feedback{padding:12px 14px;border-radius:12px;margin-top:14px;font-weight:700}.kq-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.kq-btn{border:0;border-radius:12px;padding:12px 16px;background:#7048e8;color:#fff;font-weight:800}.kq-btn:disabled{opacity:.45}.kq-btn.secondary{background:#f0ebff;color:#7048e8}.kq-video{width:100%;max-height:280px;background:#101522;border-radius:12px;margin-top:12px}.kq-empty{text-align:center;padding:35px 20px}.kq-results{text-align:center;padding:24px}.kq-results strong{display:block;font-size:2.2rem;color:#7048e8;margin:12px}@media(max-width:850px){.kq-layout{grid-template-columns:1fr}.kq-image-wrap{height:280px}}@media(max-width:560px){.kq-answers{grid-template-columns:1fr}.kq-card{padding:16px}.kq-image-wrap{height:230px}}
</style>
<div class="kidss-quiz"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><h1>Sign Language Quiz</h1><p class="kq-muted mb-0">Practice from the lessons published by your teacher. Your progress is saved to your account.</p></div><div class="text-end"><small class="kq-muted">Current score</small><div id="kqScore" class="h4 fw-bold mb-0">0</div></div></div>
<div id="kqNotice" class="alert d-none mt-3" role="status"></div>
<div class="kq-toolbar"><div><label for="kqCategory">Lesson category</label><select id="kqCategory"><option>Loading categories…</option></select></div><div class="kq-muted small" id="kqSaveStatus" aria-live="polite">Loading saved quiz progress…</div></div>
<div class="kq-progress"><span id="kqProgressBar" style="width:0%"></span></div><div id="kqContent"><div class="kq-card kq-empty">Loading published lesson questions…</div></div></div>
<script>
(function(){
 const endpoint='api/student_quiz.php',categorySelect=document.getElementById('kqCategory'),content=document.getElementById('kqContent'),notice=document.getElementById('kqNotice'),scoreLabel=document.getElementById('kqScore'),bar=document.getElementById('kqProgressBar'),saveStatus=document.getElementById('kqSaveStatus');
 if(!content||content.dataset.bound)return;content.dataset.bound='1';
 let data=null,items=[],itemById={},order=[],answers={},index=0,score=0,completed=false,choices=[],answered=false,modalVideo=null;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function msg(t,ok=false){notice.className='alert '+(ok?'alert-success':'alert-danger');notice.textContent=t}
 async function request(url,body){const r=await fetch(url,{credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok||!d.success)throw Error(d.message||'Request failed');return d}
 function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
 function currentItem(){return itemById[Number(order[index])]}
 function updateHeader(){scoreLabel.textContent=score+' / '+order.length;bar.style.width=(order.length?Math.min(100,index/order.length*100):0)+'%'}
 function choicesFor(item){const wrong=shuffle(items.filter(x=>Number(x.lesson_id)!==Number(item.lesson_id))).slice(0,3).map(x=>x.title);return shuffle([item.title,...wrong])}
 function render(){
  if(completed){showResults();return}
  if(!items.length){content.innerHTML='<div class="kq-card kq-empty"><i class="bi bi-image fs-1"></i><h2 class="h4 mt-3">No picture questions available</h2><p class="kq-muted">This category has no published lessons with an image. Ask your teacher to add an image to a published lesson.</p></div>';return}
  if(order.length<2){content.innerHTML='<div class="kq-card kq-empty"><h2 class="h4">Not enough picture lessons</h2><p class="kq-muted">A quiz needs at least two published lessons with images in this category.</p></div>';return}
  if(index>=order.length){finish();return}
  const item=currentItem();if(!item){content.innerHTML='<div class="kq-card kq-empty">The published lessons changed. Reload this quiz to sync the question list.</div>';return}
  const prior=answers[String(item.lesson_id)];answered=!!prior;choices=choicesFor(item);
  content.innerHTML='<div class="kq-layout"><section class="kq-card"><div class="kq-muted small">Question '+(index+1)+' of '+order.length+'</div><div class="kq-image-wrap"><img src="'+esc(item.image)+'" alt="Sign-language question image for '+esc(item.title)+'" onerror="this.style.display=\'none\';this.parentNode.insertAdjacentHTML(\'beforeend\',\'<p class=&quot;kq-muted&quot;>Image unavailable</p>\')"></div><p class="kq-question">Which lesson or sign is shown in the picture?</p><div class="kq-actions"><button class="kq-btn secondary" type="button" id="kqAudio"><i class="bi bi-volume-up-fill"></i> Play Sound</button>'+(item.video?'<button class="kq-btn secondary" type="button" id="kqVideo"><i class="bi bi-play-circle-fill"></i> Watch Sign</button>':'')+'</div><div id="kqMedia"></div></section><section class="kq-card"><div class="kq-question mb-3">Choose one answer</div><div class="kq-answers" id="kqAnswers">'+choices.map((v,i)=>'<button type="button" class="kq-answer" data-answer="'+esc(v)+'"><span class="kq-letter">'+String.fromCharCode(65+i)+'</span><span>'+esc(v)+'</span></button>').join('')+'</div><div id="kqFeedback"></div><div class="kq-actions"><button type="button" class="kq-btn" id="kqNext" '+(answered?'':'disabled')+'>'+(index===order.length-1?'Finish quiz':'Next question')+' <i class="bi bi-arrow-right"></i></button></div></section></div>';
  const answerButtons=content.querySelectorAll('[data-answer]');answerButtons.forEach(b=>{if(prior){b.disabled=true;if(b.dataset.answer===item.title)b.classList.add('correct');if(b.dataset.answer===prior.selected&&prior.selected!==item.title)b.classList.add('wrong')}b.addEventListener('click',()=>choose(b.dataset.answer,item))});
  if(prior){document.getElementById('kqFeedback').innerHTML='<div class="kq-feedback '+(prior.correct?'alert-success':'alert-danger')+'">'+(prior.correct?'Correct!':'Correct answer: '+esc(item.title))+'</div>'}
  document.getElementById('kqNext').addEventListener('click',async()=>{if(!answered)return;index++;if(index>=order.length){await finish()}else{await persist();render()}});
  document.getElementById('kqAudio').addEventListener('click',()=>{if(item.audio){const a=new Audio(item.audio);a.play().catch(()=>msg('Audio could not be played in this browser.'))}else if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(item.title))}else msg('No audio is available for this lesson.')});
  const vb=document.getElementById('kqVideo');if(vb)vb.addEventListener('click',()=>{document.getElementById('kqMedia').innerHTML='<video class="kq-video" controls playsinline src="'+esc(item.video)+'"></video>';const v=document.querySelector('.kq-video');v.play().catch(()=>{})});
  updateHeader();
 }
 async function persist(){try{await request(endpoint,{action:'save_state',category_id:Number(data.category_id),question_index:index,score,question_order:order,answers});saveStatus.textContent='Saved to your account';}catch(e){saveStatus.textContent='Save failed';msg(e.message)}}
 async function choose(selected,item){if(answered)return;answered=true;const correct=selected===item.title;answers[String(item.lesson_id)]={selected,correct};if(correct)score++;content.querySelectorAll('[data-answer]').forEach(b=>{b.disabled=true;if(b.dataset.answer===item.title)b.classList.add('correct');if(b.dataset.answer===selected&&!correct)b.classList.add('wrong')});document.getElementById('kqFeedback').innerHTML='<div class="kq-feedback '+(correct?'alert-success':'alert-danger')+'">'+(correct?'Correct! Well done.':'The correct answer is '+esc(item.title)+'.')+'</div>';document.getElementById('kqNext').disabled=false;scoreLabel.textContent=score+' / '+order.length;await persist()}
 async function finish(){completed=true;bar.style.width='100%';try{await request(endpoint,{action:'complete',category_id:Number(data.category_id),score,total_items:order.length,question_order:order,answers});saveStatus.textContent='Result saved to your account';}catch(e){completed=false;msg(e.message);return}showResults()}
 function showResults(){bar.style.width='100%';scoreLabel.textContent=score+' / '+order.length;const pct=order.length?Math.round(score/order.length*100):0;content.innerHTML='<div class="kq-card kq-results"><div class="display-4 text-warning"><i class="bi bi-trophy-fill"></i></div><h2 class="h3 fw-bold">Quiz progress saved</h2><p class="kq-muted">Your completed attempt is stored in the database. Opening this category again will keep this result until you choose to start a new attempt.</p><strong>'+score+' / '+order.length+' ('+pct+'%)</strong><p>'+(pct>=75?'Great work! You passed this practice quiz.':'Keep practicing and try again when you are ready.')+'</p><button type="button" class="kq-btn" id="kqRestart">Start a new attempt</button></div>';document.getElementById('kqRestart').addEventListener('click',restart)}
 async function restart(){const ids=shuffle(items.map(x=>Number(x.lesson_id)));try{await request(endpoint,{action:'restart',category_id:Number(data.category_id),question_order:ids});order=ids;answers={};index=0;score=0;completed=false;saveStatus.textContent='New attempt started';msg('A new attempt has started. Your previous completed result remains in your quiz history.',true);await persist();render()}catch(e){msg(e.message)}}
 async function load(categoryId){content.innerHTML='<div class="kq-card kq-empty">Loading your published lessons and saved progress…</div>';try{data=await request(endpoint+'?'+(categoryId?'category_id='+encodeURIComponent(categoryId):''));categorySelect.innerHTML=(data.categories||[]).map(c=>'<option value="'+c.category_id+'">'+esc(c.category_name)+'</option>').join('');if(!data.categories||!data.categories.length){content.innerHTML='<div class="kq-card kq-empty">No active lesson categories are available yet.</div>';return}categorySelect.value=String(data.category_id);items=data.items||[];itemById={};items.forEach(i=>itemById[Number(i.lesson_id)]=i);const state=data.state;
 const availableIds=items.map(i=>Number(i.lesson_id));
 const savedOrder=state&&Array.isArray(state.question_order)?state.question_order.map(Number):[];
 const savedSet=new Set(savedOrder);
 const savedOrderValid=!!state&&savedOrder.length>0&&savedSet.size===savedOrder.length&&savedOrder.every(id=>itemById[id])&&availableIds.every(id=>savedSet.has(id));
 const savedIndex=state?Number(state.question_index):0;
 const resetState=!savedOrderValid||!Number.isInteger(savedIndex)||savedIndex<0||(!state?.completed&&savedIndex>=savedOrder.length);
 if(state&&!resetState){
  order=savedOrder;answers=state.answers&&typeof state.answers==='object'&&!Array.isArray(state.answers)?state.answers:{};score=Number(state.score)||0;index=Math.min(savedIndex,Math.max(0,order.length-1));completed=!!state.completed;
 }else{
  order=shuffle(availableIds);answers={};index=0;score=0;completed=false;
  if(order.length)await request(endpoint,{action:'restart',category_id:Number(data.category_id),question_order:order});
 }
 saveStatus.textContent=state&&!resetState?'Saved progress loaded · '+(state.updated_at||''):(resetState?'Outdated quiz progress reset':'New attempt');
 if(!completed&&order.length)await persist();render()
 }catch(e){content.innerHTML='<div class="kq-card kq-empty">'+esc(e.message)+'</div>';msg(e.message)}}
 categorySelect.addEventListener('change',()=>load(Number(categorySelect.value)));load();
})();
</script>